#!/usr/bin/env python3
"""Public fixed read-only disabled-scope contract; no USB/private inputs.

Reuse the canonical process scan, bootstrap pins and script-size deltas rather
than maintaining another hand-written list. Source hashes let the future private
SDK join compare this reader with its separately admitted frozen source closure.
--check only compares generated bytes. Nothing is executed on a monitor.
"""
import argparse
import hashlib
import importlib
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[2]
PORT = ROOT / 'ports/monitor1'
sys.path.insert(0, str(PORT))
try:
    review = importlib.import_module('review_disabled_install')
    bootstrap = importlib.import_module('bootstrap_patches')
    preflight = importlib.import_module('preflight_adb')
finally:
    sys.path.pop(0)


def specification():
    start, watchdog = '/data/etc/init.d/start.sh', '/data/bin/watchdog.sh'
    value = {'process_scan': review.PROCESS_SCAN,
        'patched': {start: {'sha256': bootstrap.START_INSTALLED, 'size': preflight.FILES[start][1] + 298},
                    watchdog: {'sha256': bootstrap.WATCHDOG_INSTALLED,
                        'size': preflight.FILES[watchdog][1] + len(bootstrap.WATCHDOG_NEW) - len(bootstrap.WATCHDOG_OLD)}},
        'sources': review.policy.SOURCES,
        'source_sha256': {name: hashlib.sha256((PORT / name).read_bytes()).hexdigest() for name in
                          ('review_disabled_install.py', 'bootstrap_patches.py', 'preflight_adb.py', 'disabled_commit_policy.py')}}
    return value


def content():
    value = specification()
    return ('// Generated by tools/monitor1-usb/generate_disabled_contract.py; public read-only inputs.\n'
            'export const disabledContract = ' + json.dumps(value, indent=2, ensure_ascii=True) + ';\n')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    outputs = {
        ROOT / 'custom_components/qingping_esphome/frontend/usb-disabled-contract.mjs': content(),
        ROOT / 'apps/monitor1_usb/rootfs/disabled-contract.json': json.dumps(specification(), indent=2) + '\n',
    }
    for path, data in outputs.items():
        if args.check:
            if not path.is_file() or path.read_text() != data:
                raise SystemExit('Disabled scope contract is stale')
        else:
            path.write_text(data)



if __name__ == '__main__':
    main()
